-- Initial PostgreSQL schema port for R&R POS. No production data is imported.
-- Plaintext password storage is intentionally omitted; migrate auth to Supabase Auth before production use.
create table if not exists public.account_change_requests (request_id text primary key, request_type text, user_id text, current_username text, proposed_value text, requested_auth_version text, requested_at text, status text, reviewed_by text, reviewed_at text, decision_note text);
create table if not exists public.activity_reads (user_id text, log_id text, read_at text, primary key (user_id, log_id));
create table if not exists public.trash_requests (request_id text primary key, request_type text, trash_ids text, trash_names text, requested_by text, requester_id text, requested_at text, proposed_reason text, status text, reviewed_by text, reviewed_at text, decision_note text);
create table if not exists public.password_requests (request_id text primary key, username text, user_id text, display_name text, requested_at text, status text, handled_by text, handled_at text, request_details text);
create table if not exists public.change_history (history_id text primary key, log_id text, datetime text, target_date text, action text, "user" text, changes_json text, status text, rolled_back_by text, rolled_back_at text);
create table if not exists public.user_sessions (token_hash text primary key, user_id text, auth_version integer, issued_at text, device_id text);
create table if not exists public.users (user_id text primary key, username text, display_name text, password_hash text, password_salt text, role text, active integer, created_at text, last_login text, device_id text, auth_version integer, password_algorithm text not null default 'pbkdf2_sha256_150000');
create unique index if not exists idx_users_username on public.users (lower(username));
create table if not exists public.user_access_log (device_id text primary key, device_name text, user_name text, ip_address text, first_seen text, last_seen text, visits integer, user_agent text, enabled integer, notes text);
create table if not exists public.activity_log (datetime text, action text, record text, details text, "user" text, ip_address text, device_id text, log_id text primary key);
create index if not exists idx_activity_log_datetime on public.activity_log (datetime);
create index if not exists idx_activity_log_user on public.activity_log ("user");
create table if not exists public.cash_reconciliation (date text primary key, expected_cash_sales double precision, opening_float double precision, cash_expenses double precision, actual_counted double precision, notes text, saved_at text);
create table if not exists public.trash (trash_id text primary key, source_tab text, record_id text, record_name text, reason text, deleted_at text, record_json text);
create table if not exists public.products (product_id text primary key, product_name text, category text, brand text, unit text, cost_price double precision, selling_price double precision, stock double precision, min_stock double precision, supplier text, pack_size double precision, unit_price double precision, stock_units double precision, pack_type text, pack_cost double precision, flavor text, added_at text, sku_barcode text, expiration_date text, sku_barcode_2 text, owner_name text not null default '');
create index if not exists idx_products_name on public.products (product_name);
create index if not exists idx_products_category on public.products (category);
create index if not exists idx_products_sku on public.products (sku_barcode);
create table if not exists public.sales (date text, transaction_id text primary key, items integer, total double precision, profit double precision, payment double precision, change double precision, item_details text, time text, payment_method text, datetime text, payment_transaction_id text);
create index if not exists idx_sales_date on public.sales (date);
create index if not exists idx_sales_datetime on public.sales (datetime);
create table if not exists public.customers (customer_id text primary key, name text, contact text, utang_balance double precision, last_transaction text, last_datetime text);
create table if not exists public.suppliers (supplier_id text primary key, supplier_name text, contact text, products text, last_purchase text, last_datetime text);
create table if not exists public.categories (category text primary key);
create table if not exists public.stock_movement (movement_id bigint generated by default as identity primary key, date text, product_id text, type text, quantity double precision, reason text, datetime text);
create index if not exists idx_stock_movement_product on public.stock_movement (product_id);
create index if not exists idx_stock_movement_date on public.stock_movement (date);
create table if not exists public.settings (key text primary key, value text);
create table if not exists public.login_attempts (username_key text not null, ip_key text not null, attempts integer not null default 0, window_start text not null, primary key (username_key, ip_key));
create table if not exists public.cash_management_daily (date text primary key, fund_from_yesterday double precision not null default 0, opening_cash_float double precision not null default 0, total_sales_today double precision not null default 0, cash_sales_today double precision not null default 0, total_expenses double precision not null default 0, cash_on_hand_now double precision not null default 0, fund_source_date text not null default '', notes text not null default '', saved_by text not null default '', saved_by_id text not null default '', saved_at text not null default '', sales_adjustment double precision not null default 0, cash_sales_adjustment double precision not null default 0, physical_cash_on_hand double precision not null default 0, gcash_balance double precision not null default 0);
create index if not exists idx_cash_management_daily_date on public.cash_management_daily(date);
create table if not exists public.cash_management_expenses (expense_id text primary key, business_date text not null, expense_name text not null, amount double precision not null default 0, receipt_image text not null default '', created_by text not null default '', created_by_id text not null default '', created_at text not null default '');
create index if not exists idx_cash_management_expenses_date on public.cash_management_expenses(business_date);
create table if not exists public.cash_management_corrections (correction_id text primary key, business_date text not null, original_amount double precision not null default 0, corrected_amount double precision not null default 0, reason text not null, corrected_by text not null, corrected_by_id text not null, corrected_by_role text not null, corrected_at text not null);
create index if not exists idx_cash_management_corrections_date on public.cash_management_corrections(business_date, corrected_at);
create table if not exists public.cash_management_record_history (history_id text primary key, business_date text not null, action text not null default 'RESTARTED', record_json text not null, expenses_json text not null default '[]', reason text not null default '', actor_name text not null default '', actor_id text not null default '', actor_role text not null default '', created_at text not null);
create table if not exists public.gcash_transactions (transaction_id text primary key, date text not null, time text, service_type text not null check (service_type in ('CASH_IN','CASH_OUT','LOAD','BILLS_PAYMENT','POS_SALE')), customer_name text not null default '', biller_name text not null default '', amount double precision not null check (amount > 0), fee double precision not null check (fee >= 0), sale_transaction_id text not null, created_at text not null, created_by text, created_by_id text, payment_source text not null default '', receipt_data text, receipt_file_name text, receipt_content_type text, receipt_size integer, receipt_uploaded_at text, receipt_uploaded_by text);
create index if not exists idx_gcash_transactions_date on public.gcash_transactions(date);
create index if not exists idx_gcash_transactions_sale on public.gcash_transactions(sale_transaction_id);
create index if not exists idx_gcash_transactions_created_at on public.gcash_transactions(created_at);
create table if not exists public.gcash_wallet_balance (wallet_id text primary key check (wallet_id = 'default'), balance double precision not null default 0 check (balance >= 0), updated_at text not null, updated_by text not null default '', updated_by_id text not null default '', baseline_date text not null default '');
create table if not exists public.gcash_balance_movements (movement_id text primary key, movement_date text not null, movement_type text not null, reference_id text not null default '', description text not null default '', amount_delta double precision not null, created_at text not null, created_by text not null default '', created_by_id text not null default '');
create index if not exists idx_gcash_balance_movements_reference on public.gcash_balance_movements(reference_id);
create index if not exists idx_gcash_balance_movements_date on public.gcash_balance_movements(movement_date);
create table if not exists public.cash_management_report_expenses (expense_id text primary key, date text not null, category text not null default 'Other', description text not null, amount double precision not null check (amount > 0), receipt_data text not null default '', receipt_file_name text not null default '', receipt_content_type text not null default '', receipt_size integer not null default 0, created_at text not null default '', created_by text not null default '', created_by_id text not null default '', updated_at text not null default '', updated_by text not null default '', updated_by_id text not null default '');
create index if not exists idx_cash_management_report_expenses_date on public.cash_management_report_expenses(date, created_at desc);
create table if not exists public.cash_management_report_cash_movements (movement_id text primary key, movement_date text not null, movement_type text not null default 'POS_SALE_CASH', reference_id text not null default '', description text not null default '', amount_delta double precision not null, created_at text not null default '', created_by text not null default '', created_by_id text not null default '');
-- Lock all tables until the API is migrated and authenticated.
do $$
declare r record;
begin
  for r in select tablename from pg_tables where schemaname = 'public' and tablename <> 'schema_migrations'
  loop
    execute format('alter table public.%I enable row level security', r.tablename);
    execute format('revoke all on table public.%I from anon, authenticated', r.tablename);
  end loop;
end $$;
revoke all on all sequences in schema public from anon, authenticated;